{
 "command": "ls tests tests/* ; cat .engramdb/memories/database-connections* | grep -n -i -A3 -B3 statement",
 "description": "List tests and check memory mentioning statements"
}

{
 "command": "cat tests/goldens.py tests/golden/MANIFEST tests/golden/statement_basic.txt tests/golden/inputs/*; ls tests/golden/inputs; git log --stat | head -40",
 "description": "Inspect golden helpers and fixtures"
}

{
 "command": "python scripts/regen_goldens.py && git diff tests/ && python -m unittest discover -s tests -t . 2>&1 | tail -5",
 "description": "Regenerate goldens, show diff, run tests"
}

{
 "command": "python -m unittest tests.test_statements -v 2>&1 | tail -5; python -m pytest -q 2>&1 | tail -5",
 "description": "Run statement tests and full suite"
}

{
 "command": "git stash -q && python -m pytest -q 2>&1 | tail -5; git stash pop -q && git status --short",
 "description": "Confirm the other failures already existed before the change"
}
